**Full Contents:**

```typescript
import { Block, Text } from "@prototyp/skeletor";
import {
  type EventTimelineItem,
  type ImageMessageContent,
  MessageType_Tags,
  MsgLikeKind_Tags,
  TimelineItemContent_Tags,
  type UserProfile,
} from "@unomed/react-native-matrix-sdk";
import { format } from "date-fns";
import { useSetAtom } from "jotai";
import { MatrixBaseURL } from "modules/matrix-client/const";
import { MatrixService } from "modules/matrix-client/services";
import { fetchMedia, getEventTextContent } from "modules/matrix-client/utils";
import { TimelineAtoms } from "modules/timeline/jotai";
import { type FC, useCallback, useEffect, useState } from "react";
import { Image } from "react-native";
import { Loading, PinIndicator, SeenBy } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { MessageLongPressWrapper } from "../message-long-press-wrapper";
import { MessageSender } from "../message-sender";

interface Props {
  event: EventTimelineItem;
  isPreviousSameSender: boolean;
}

const MAX_DIMENSION = 300;

const getImageContent = (
  event: EventTimelineItem,
): ImageMessageContent | null => {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;
      if (msgType?.tag === MessageType_Tags.Image) {
        return msgType.inner.content;
      }
    }
  }
  return null;
};

export const ImageMessage: FC<Props> = ({ event, isPreviousSameSender }) => {
  const content = getImageContent(event);
  const [messageWidth, setMessageWidth] = useState(40);
  const originalWidth = Number(content?.info?.thumbnailInfo?.width) || 0;
  const originalHeight = Number(content?.info?.thumbnailInfo?.height) || 0;
  const scaleRatio = Math.min(
    MAX_DIMENSION / originalWidth,
    MAX_DIMENSION / originalHeight,
    1,
  );
  const targetWidth = Math.round(originalWidth * scaleRatio);
  const targetHeight = Math.round(originalHeight * scaleRatio);
  const [uri, setUri] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const isUser = event.isOwn;
  const sender = event.senderProfile;
  const senderId = event.sender;
  const caption = content?.caption;
  const [seenBy, setSeenBy] = useState<UserProfile[]>([]);
  const setImageViewerUri = useSetAtom(TimelineAtoms.imageViewerUri);

  const openImageViewer = useCallback(() => {
    if (!uri || isLoading) return;
    setImageViewerUri(uri);
  }, [uri, isLoading, setImageViewerUri]);

  useEffect(() => {
    MatrixService.getReadReceipts(event)
      .then((users) => {
        setSeenBy(users);
      })
      .catch((error) => {
        console.error("Failed to get read receipt users:", error);
        setSeenBy([]);
      });
  }, [event]);

  useEffect(() => {
    if (!content?.source.url()) return;

    fetchMedia({
      serverUrl:
        MatrixService.instance?.session().homeserverUrl || MatrixBaseURL,
      mediaSource: content.source,
      mimeType: content.info?.mimetype || "image/jpeg",
    })
      .then(setUri)
      .catch(console.error)
      .finally(() => setIsLoading(false));
  }, [content]);

  if (!content) return null;

  return (
    <Block
      align={isUser ? "flex-end" : "flex-start"}
      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
    >
      <MessageSender
        sender={sender}
        senderId={senderId}
        isUser={isUser}
        isPreviousSameSender={isPreviousSameSender}
      />
      <MessageLongPressWrapper
        event={event}
        content={getEventTextContent(event)}
        onFinalize={openImageViewer}
      >
        <Block
          background="transparent"
          border={{
            borderRadius: 12,
          }}
          align="center"
          overflow="hidden"
          width={targetWidth}
          height={targetHeight}
          onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
        >
          {isLoading ? (
            <Block
              width="100%"
              height="100%"
              background={Colors.white20}
              align="center"
              justify="center"
            >
              <Loading isFullScreen={false} />
            </Block>
          ) : uri ? (
            <Image
              source={{ uri }}
              width={targetWidth}
              height={targetHeight}
              resizeMode="contain"
            />
          ) : null}
        </Block>
      </MessageLongPressWrapper>
      <Block
        align={isUser ? "flex-end" : "flex-start"}
        margins={{ marginTop: 12 }}
      >
        {caption ? (
          <Block
            paddings={12}
            background={isUser ? Colors.primary : Colors.message}
            border={{
              borderRadius: 24,
            }}
            flexDirection={isUser ? "row-reverse" : "row"}
            gap={{
              row: 4,
              col: 16,
            }}
            align="center"
            flex={{ flexWrap: "wrap" }}
            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
          >
            <Text size={TextSize.small} color="white">
              {caption}
            </Text>
            <Block
              flexDirection={isUser ? "row" : "row-reverse"}
              gap={4}
              align="center"
            >
              <PinIndicator event={event} />
              <Text size={TextSize.tiny} color={Colors.white50}>
                {format(Number(event.timestamp), "HH:mm")}
              </Text>
            </Block>
          </Block>
        ) : (
          <Block
            flexDirection={isUser ? "row" : "row-reverse"}
            gap={4}
            align="center"
          >
            <PinIndicator event={event} />
            <Text size={TextSize.tiny} color={Colors.white50}>
              {format(Number(event.timestamp), "HH:mm")}
            </Text>
          </Block>
        )}
      </Block>
      <SeenBy seenBy={seenBy} messageWidth={messageWidth} />
    </Block>
  );
};
```

The ImageMessage component is a React Native functional component that handles the display of image messages in the room timeline. It features:
- Image scaling with a maximum dimension of 300px
- Loading state with spinner
- Caption support
- Timestamp display with HH:mm format
- Pin indicator and read receipts (seen by)
- Image viewer integration via Jotai atoms
- Responsive layout for both user and other sender messages
